def benchImp (b : Bool) (xs : List Nat) : Except Unit (List Nat) :=
  Id.run do
    if b then
      return .error ()
    let mut acc : Array Nat := #[]
    for i in xs do
      acc := acc.push (i + 1)
    return .ok acc.toList

def benchFun (b : Bool) (xs : List Nat) : Except Unit (List Nat) :=
  if b then .error () else .ok (xs.map (· + 1))

theorem bench_eq (b : Bool) (xs : List Nat) : benchImp b xs = benchFun b xs := by
  cases b <;> simp [benchImp, benchFun, Id.run, List.forIn_pure_yield_eq_foldl, bind_pure_comp] <;> rfl

